@startuml

class Provider {
  + Name : string
  + Location : string
}

class Cruise {
  + Number : int
  + Name : string
  + StartDate : date
  + EndDate : date
}

class Employee {
  + Name : string
  + Ssn : int
}

class Guest {
  + Name : string
  + VIP : boolean
}

class Ship {
  + Name : string
  + DeckCount : int
  + Length : float
  + PassengerCount : int
}

class TravelAgency {
  + Name : string
  + Address : string
}

class Booking {
  + BookingNumber : int
  + BookingDate : date
}

class Destination {
  + Name : string
  + Sea : string
}

class Show {
  + Title : string
  + Duration : int
}

class Ticket {
}

Provider "1" -- "0..*" Cruise
Cruise "0..*" -- "1..*" Employee
Cruise "0..*" -- "0..*" Guest
Cruise "0..*" -- "0..1" Ship
Cruise "0..*" -- "0..1" Destination
Cruise "0..*" -- "0..*" Show
TravelAgency "1" -- "0..*" Booking
Booking "0..*" -- "1" Cruise
Cruise "1" -- "0..*" Ticket
Ticket "0..*" -- "1" Guest
Guest "0..*" -- "0..*" Cruise

@enduml

